package com.aegis.erp.modules.planilla.cuentabancaria;import com.aegis.erp.modules.planilla.empleado.EmpleadoOptionResponse;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/planilla/cuentas-bancarias-empleados")public class CuentaBancariaController{private final CuentaBancariaService service;public CuentaBancariaController(CuentaBancariaService service){this.service=service;}@GetMapping@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','CONSULTAR')")public List<CuentaBancariaResponse>listar(@RequestParam(required=false)String search){return service.listar(search);}@PostMapping@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','ALTA')")public CuentaBancariaResponse crear(@Valid@RequestBody CuentaBancariaRequest r,JwtAuthenticationToken a){return service.crear(r,a.getName());}@PutMapping("/{id}")@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','CAMBIO')")public CuentaBancariaResponse modificar(@PathVariable Long id,@Valid@RequestBody CuentaBancariaRequest r,JwtAuthenticationToken a){return service.modificar(id,r,a.getName());}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','BAJA')")public void eliminar(@PathVariable Long id){service.eliminar(id);}@GetMapping("/options/empleados")@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','CONSULTAR')")public List<EmpleadoOptionResponse>empleados(@RequestParam(required=false)String search){return service.empleados(search);}@GetMapping("/options/bancos")@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','CONSULTAR')")public List<EmpleadoOptionResponse>bancos(){return service.bancos();}@GetMapping("/print")@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','IMPRIMIR')")public List<CuentaBancariaResponse>print(@RequestParam(required=false)String search){return service.listar(search);}@GetMapping(value="/export/excel",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','EXPORTAR')")public ResponseEntity<byte[]>excel(@RequestParam(required=false)String search){return file(service.excel(search),"cuentas-bancarias.xlsx",MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"));}@GetMapping(value="/export/pdf",produces=MediaType.APPLICATION_PDF_VALUE)@PreAuthorize("@permissionAuthorizationService.allowed(authentication.name,'cuenta_bancaria_empleado','EXPORTAR')")public ResponseEntity<byte[]>pdf(@RequestParam(required=false)String search){return file(service.pdf(search),"cuentas-bancarias.pdf",MediaType.APPLICATION_PDF);}private ResponseEntity<byte[]>file(byte[]b,String n,MediaType t){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+n).contentType(t).body(b);}}
